#!/bin/sh
# Generated by FWShift: an AWS Network Firewall policy and its stateful rule group, created with the AWS CLI. Read the
# report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE    prints the calls, makes none (no AWS access needed)
#   CHECK=1 sh THIS_FILE      sends every call with --dry-run: AWS checks the requests and the permissions
#   sh THIS_FILE              creates the rule group and the policy
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The policy is attached to no firewall: nothing changes for any traffic until you associate it:
#   aws network-firewall associate-firewall-policy --firewall-name FIREWALL --firewall-policy-arn ARN
# A rule group or policy of the same name stops the script before anything is created; a call AWS refuses stops it
# where it is (delete what it made with aws network-firewall delete-rule-group / delete-firewall-policy and run it
# again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws network-firewall' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
TMP=$(mktemp -d) || fail "mktemp"
trap 'rm -rf "$TMP"' EXIT
# free_group NAME / free_policy NAME: stop the script when one of that name exists
free_group() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-rule-group --rule-group-name "$1" --type STATEFUL $AWS_OPTS >/dev/null 2>&1; then
    fail "a rule group named $1 exists already; nothing was created"
  fi
}
free_policy() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-firewall-policy --firewall-policy-name "$1" $AWS_OPTS >/dev/null 2>&1; then
    fail "a firewall policy named $1 exists already; nothing was created"
  fi
}
# group NAME CAPACITY FILE: creates a stateful rule group and prints its ARN
group() {
  if [ -n "$DRY_RUN" ]; then
    show create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3"
    printf 'arn:aws:network-firewall:dryrun:000000000000:stateful-rulegroup/%s\n' "$1"
    return 0
  fi
  if [ -n "$CHECK" ]; then
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --dry-run --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1 (dry run)"
    printf 'checked: rule group %s\n' "$1" >&2
  else
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --description 'Generated by FWShift' --tags Key=fwshift,Value=generated \
      --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1"
    printf 'created %s\n' "$arn" >&2
  fi
  printf '%s\n' "$arn"
}
# policy NAME FILE CHECKFILE: creates the firewall policy (with CHECK, checks it without its rule groups, which a dry run
# does not create)
policy() {
  if [ -n "$DRY_RUN" ]; then show create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2"; return 0; fi
  if [ -n "$CHECK" ]; then
    aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$3" --dry-run $AWS_OPTS >/dev/null \
      || fail "create-firewall-policy $1 (dry run)"
    printf 'checked: firewall policy %s\n' "$1" >&2
    return 0
  fi
  aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2" \
    --description 'Generated by FWShift; review the conversion report before associating it' \
    --tags Key=fwshift,Value=generated $AWS_OPTS >/dev/null || fail "create-firewall-policy $1"
  printf 'created firewall policy %s\n' "$1" >&2
}

# No rule group or policy of these names may exist.
free_group fwshift-rules
free_policy fwshift

# Rule group 1: 8 rules, in the order of the policy.
cat > "$TMP/group1.json" <<'FWSHIFT_JSON'
{
 "RuleVariables": {
  "IPSets": {
   "admins": {
    "Definition": [
     "192.168.10.50/31",
     "192.168.10.52/30",
     "192.168.10.56/30"
    ]
   },
   "lan6": {
    "Definition": [
     "2001:db8:10::/64"
    ]
   },
   "partners_ipv6": {
    "Definition": [
     "2001:db8:99::/48"
    ]
   }
  }
 },
 "RulesSource": {
  "RulesString": "drop ip $admins any -> any any (msg:\"nothing but TCP\"; flow:to_server; ip_proto:!6; sid:1; rev:1;)\ndrop ip !$admins any -> 0.0.0.0/0 any (msg:\"nothing but TCP-2\"; flow:to_server; ip_proto:!6; sid:2; rev:1;)\nreject tcp 0.0.0.0/0 any -> any [80,443] (msg:\"no other web from guests\"; flow:to_server; sid:3; rev:1;)\ndrop ip 0.0.0.0/0 any -> any any (msg:\"no guests elsewhere\"; flow:to_server; sid:4; rev:1;)\ndrop ip 0.0.0.0/0 any -> any any (msg:\"defconf: drop all from WAN not DSTNATed\"; flow:to_server; sid:5; rev:1;)\npass icmp ::/0 any -> any any (msg:\"ICMPv6 echo\"; flow:to_server; ip_proto:58; itype:128; sid:6; rev:1;)\npass tcp $partners_ipv6 any -> $lan6 443 (msg:\"the partners reach the web servers of the LAN by HTTPS and nothing else\"; flow:to_server; sid:7; rev:1;)\ndrop ip ::/0 any -> any any (msg:\"drop everything else not coming from LAN\"; flow:to_server; sid:8; rev:1;)\n"
 },
 "StatefulRuleOptions": {
  "RuleOrder": "STRICT_ORDER"
 }
}
FWSHIFT_JSON
G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   defconf: accept in ipsec policy: not converted: ipsec-policy=in,ipsec (traffic of IPsec tunnels)
#   banned scanners: not converted: address list 'scanners', which rules fill while the router runs
#   ssh from the admins: the destination of the rule is in zone DMZ, and a rule of Network Firewall names no zone: give the networks behind DMZ with --zone-network
#   web for everyone: the destination of the rule is in zone DMZ, and a rule of Network Firewall names no zone: give the networks behind DMZ with --zone-network
#   web for everyone-2: the destination of the rule is in zone DMZ, and a rule of Network Firewall names no zone: give the networks behind DMZ with --zone-network
#   ping "echo" only: the destination of the rule is in zone DMZ, and a rule of Network Firewall names no zone: give the networks behind DMZ with --zone-network
#   ping "echo" only-2: the destination of the rule is in zone DMZ, and a rule of Network Firewall names no zone: give the networks behind DMZ with --zone-network
#   old partner access: disabled in the source
#   old partner access-2: disabled in the source
#   rest of the DMZ: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   rest of the DMZ-2: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   rest of the DMZ-3: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   LAN to the package mirrors: the source of the rule is in zone LAN, and a rule of Network Firewall names no zone: give the networks behind LAN with --zone-network; the addresses of the destination 'mirrors' are not known; a rule of Network Firewall names addresses
#   guest DNS, either port: the source of the rule is in zone GUEST, and a rule of Network Firewall names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   guest DNS, either port-2: the source of the rule is in zone GUEST, and a rule of Network Firewall names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   guests to the internet: the source of the rule is in zone GUEST, and a rule of Network Firewall names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   office hours for staff: schedule 'time=8h-18h,mon,tue,wed,thu,fri' is not converted; the rule would apply at all times; the source of the rule is in zone LAN, and a rule of Network Firewall names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Fir
#   defconf: drop all from WAN not DSTNATed (allows publish web): the source of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   defconf: drop all from WAN not DSTNATed (allows publish mail): the source of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
